/** @internal The base modules: each file in modules/ and its text. */
export const BASE_MODULES: readonly { readonly file: string; readonly text: string }[] = [
  { file: "ietf-netconf-monitoring@2010-10-04.yang", text: "module ietf-netconf-monitoring {\n  namespace \"urn:ietf:params:xml:ns:yang:ietf-netconf-monitoring\";\n  prefix ncm;\n\n  import ietf-yang-types {\n    prefix yang;\n  }\n  import ietf-inet-types {\n    prefix inet;\n  }\n\n  organization \"IETF NETCONF (Network Configuration) Working Group\";\n  contact\n    \"WG Web:   <http://tools.ietf.org/wg/netconf/>\n     WG List:  <mailto:netconf@ietf.org>\n\n     WG Chair: Mehmet Ersue\n               <mailto:mehmet.ersue@nsn.com>\n\n     WG Chair: Bert Wijnen\n               <mailto:bertietf@bwijnen.net>\n\n     Editor:   Mark Scott\n               <mailto:mark.scott@ericsson.com>\n\n     Editor:   Martin Bjorklund\n               <mailto:mbj@tail-f.com>\";\n  description\n    \"NETCONF Monitoring Module.\n     All elements in this module are read-only.\n\n     Copyright (c) 2010 IETF Trust and the persons identified as\n     authors of the code. All rights reserved.\n\n     Redistribution and use in source and binary forms, with or\n     without modification, is permitted pursuant to, and subject\n     to the license terms contained in, the Simplified BSD\n     License set forth in Section 4.c of the IETF Trust's\n     Legal Provisions Relating to IETF Documents\n     (http://trustee.ietf.org/license-info).\n\n     This version of this YANG module is part of RFC 6022; see\n     the RFC itself for full legal notices.\";\n\n  revision 2010-10-04 {\n    description\n      \"Initial revision.\";\n    reference \"RFC 6022: YANG Module for NETCONF Monitoring\";\n  }\n\n  typedef netconf-datastore-type {\n    type enumeration {\n      enum \"running\";\n      enum \"candidate\";\n      enum \"startup\";\n    }\n    description\n      \"Enumeration of possible NETCONF datastore types.\";\n    reference \"RFC 4741: NETCONF Configuration Protocol\";\n  }\n\n  identity transport {\n    description\n      \"Base identity for NETCONF transport types.\";\n  }\n\n  identity netconf-ssh {\n    base transport;\n    description\n      \"NETCONF over Secure Shell (SSH).\";\n    reference\n      \"RFC 4742: Using the NETCONF Configuration Protocol\n                 over Secure SHell (SSH)\";\n  }\n\n  identity netconf-soap-over-beep {\n    base transport;\n    description\n      \"NETCONF over Simple Object Access Protocol (SOAP) over\n       Blocks Extensible Exchange Protocol (BEEP).\";\n    reference\n      \"RFC 4743: Using NETCONF over the Simple Object\n                 Access Protocol (SOAP)\";\n  }\n\n  identity netconf-soap-over-https {\n    base transport;\n    description\n      \"NETCONF over Simple Object Access Protocol (SOAP)\n       over Hypertext Transfer Protocol Secure (HTTPS).\";\n    reference\n      \"RFC 4743: Using NETCONF over the Simple Object\n                 Access Protocol (SOAP)\";\n  }\n\n  identity netconf-beep {\n    base transport;\n    description\n      \"NETCONF over Blocks Extensible Exchange Protocol (BEEP).\";\n    reference\n      \"RFC 4744: Using the NETCONF Protocol over the\n                 Blocks Extensible Exchange Protocol (BEEP)\";\n  }\n\n  identity netconf-tls {\n    base transport;\n    description\n      \"NETCONF over Transport Layer Security (TLS).\";\n    reference \"RFC 5539: NETCONF over Transport Layer Security (TLS)\";\n  }\n\n  identity schema-format {\n    description\n      \"Base identity for data model schema languages.\";\n  }\n\n  identity xsd {\n    base schema-format;\n    description\n      \"W3C XML Schema Definition.\";\n    reference\n      \"W3C REC REC-xmlschema-1-20041028:\n         XML Schema Part 1: Structures\";\n  }\n\n  identity yang {\n    base schema-format;\n    description\n      \"The YANG data modeling language for NETCONF.\";\n    reference\n      \"RFC 6020:  YANG - A Data Modeling Language for the\n                  Network Configuration Protocol (NETCONF)\";\n  }\n\n  identity yin {\n    base schema-format;\n    description\n      \"The YIN syntax for YANG.\";\n    reference\n      \"RFC 6020:  YANG - A Data Modeling Language for the\n                  Network Configuration Protocol (NETCONF)\";\n  }\n\n  identity rng {\n    base schema-format;\n    description\n      \"Regular Language for XML Next Generation (RELAX NG).\";\n    reference \"ISO/IEC 19757-2:2008: RELAX NG\";\n  }\n\n  identity rnc {\n    base schema-format;\n    description\n      \"Relax NG Compact Syntax\";\n    reference \"ISO/IEC 19757-2:2008: RELAX NG\";\n  }\n\n  grouping common-counters {\n    description\n      \"Counters that exist both per session, and also globally,\n       accumulated from all sessions.\";\n    leaf in-rpcs {\n      type yang:zero-based-counter32;\n      description\n        \"Number of correct <rpc> messages received.\";\n    }\n    leaf in-bad-rpcs {\n      type yang:zero-based-counter32;\n      description\n        \"Number of messages received when an <rpc> message was expected,\n         that were not correct <rpc> messages.  This includes XML parse\n         errors and errors on the rpc layer.\";\n    }\n    leaf out-rpc-errors {\n      type yang:zero-based-counter32;\n      description\n        \"Number of <rpc-reply> messages sent that contained an\n         <rpc-error> element.\";\n    }\n    leaf out-notifications {\n      type yang:zero-based-counter32;\n      description\n        \"Number of <notification> messages sent.\";\n    }\n  }\n\n  container netconf-state {\n    config false;\n    description\n      \"The netconf-state container is the root of the monitoring\n       data model.\";\n    container capabilities {\n      description\n        \"Contains the list of NETCONF capabilities supported by the\n         server.\";\n      leaf-list capability {\n        type inet:uri;\n        description\n          \"List of NETCONF capabilities supported by the server.\";\n      }\n    }\n    container datastores {\n      description\n        \"Contains the list of NETCONF configuration datastores.\";\n      list datastore {\n        key \"name\";\n        description\n          \"List of NETCONF configuration datastores supported by\n           the NETCONF server and related information.\";\n        leaf name {\n          type netconf-datastore-type;\n          description\n            \"Name of the datastore associated with this list entry.\";\n        }\n        container locks {\n          presence\n            \"This container is present only if the datastore\n             is locked.\";\n          description\n            \"The NETCONF <lock> and <partial-lock> operations allow\n             a client to lock specific resources in a datastore.  The\n             NETCONF server will prevent changes to the locked\n             resources by all sessions except the one that acquired\n             the lock(s).\n\n             Monitoring information is provided for each datastore\n             entry including details such as the session that acquired\n             the lock, the type of lock (global or partial) and the\n             list of locked resources.  Multiple locks per datastore\n             are supported.\";\n\n          grouping lock-info {\n            description\n              \"Lock related parameters, common to both global and\n               partial locks.\";\n            leaf locked-by-session {\n              type uint32;\n              mandatory true;\n              description\n                \"The session ID of the session that has locked\n                 this resource.  Both a global lock and a partial\n                 lock MUST contain the NETCONF session-id.\n\n                 If the lock is held by a session that is not managed\n                 by the NETCONF server (e.g., a CLI session), a session\n                 id of 0 (zero) is reported.\";\n              reference \"RFC 4741: NETCONF Configuration Protocol\";\n            }\n            leaf locked-time {\n              type yang:date-and-time;\n              mandatory true;\n              description\n                \"The date and time of when the resource was\n                 locked.\";\n            }\n          }\n          choice lock-type {\n            description\n              \"Indicates if a global lock or a set of partial locks\n               are set.\";\n            container global-lock {\n              description\n                \"Present if the global lock is set.\";\n              uses lock-info;\n            }\n            list partial-lock {\n              key \"lock-id\";\n              description\n                \"List of partial locks.\";\n              reference\n                \"RFC 5717: Partial Lock Remote Procedure Call (RPC) for\n                           NETCONF\";\n              leaf lock-id {\n                type uint32;\n                description\n                  \"This is the lock id returned in the <partial-lock>\n                   response.\";\n              }\n              uses lock-info;\n              leaf-list select {\n                type yang:xpath1.0;\n                min-elements 1;\n                description\n                  \"The xpath expression that was used to request\n                   the lock.  The select expression indicates the\n                   original intended scope of the lock.\";\n              }\n              leaf-list locked-node {\n                type instance-identifier;\n                description\n                  \"The list of instance-identifiers (i.e., the\n                   locked nodes).\n\n                   The scope of the partial lock is defined by the list\n                   of locked nodes.\";\n              }\n            }\n          }\n        }\n      }\n    }\n    container schemas {\n      description\n        \"Contains the list of data model schemas supported by the\n         server.\";\n      list schema {\n        key \"identifier version format\";\n        description\n          \"List of data model schemas supported by the server.\";\n        leaf identifier {\n          type string;\n          description\n            \"Identifier to uniquely reference the schema.  The\n             identifier is used in the <get-schema> operation and may\n             be used for other purposes such as file retrieval.\n\n             For modeling languages that support or require a data\n             model name (e.g., YANG module name) the identifier MUST\n             match that name.  For YANG data models, the identifier is\n             the name of the module or submodule.  In other cases, an\n             identifier such as a filename MAY be used instead.\";\n        }\n        leaf version {\n          type string;\n          description\n            \"Version of the schema supported.  Multiple versions MAY be\n             supported simultaneously by a NETCONF server.  Each\n             version MUST be reported individually in the schema list,\n             i.e., with same identifier, possibly different location,\n             but different version.\n\n             For YANG data models, version is the value of the most\n             recent YANG 'revision' statement in the module or\n             submodule, or the empty string if no 'revision' statement\n             is present.\";\n        }\n        leaf format {\n          type identityref {\n            base schema-format;\n          }\n          description\n            \"The data modeling language the schema is written\n             in (currently xsd, yang, yin, rng, or rnc).\n             For YANG data models, 'yang' format MUST be supported and\n             'yin' format MAY also be provided.\";\n        }\n        leaf namespace {\n          type inet:uri;\n          mandatory true;\n          description\n            \"The XML namespace defined by the data model.\n\n             For YANG data models, this is the module's namespace.\n             If the list entry describes a submodule, this field\n             contains the namespace of the module to which the\n             submodule belongs.\";\n        }\n        leaf-list location {\n          type union {\n            type enumeration {\n              enum \"NETCONF\";\n            }\n            type inet:uri;\n          }\n          description\n            \"One or more locations from which the schema can be\n             retrieved.  This list SHOULD contain at least one\n             entry per schema.\n\n             A schema entry may be located on a remote file system\n             (e.g., reference to file system for ftp retrieval) or\n             retrieved directly from a server supporting the\n             <get-schema> operation (denoted by the value 'NETCONF').\";\n        }\n      }\n    }\n    container sessions {\n      description\n        \"The sessions container includes session-specific data for\n         NETCONF management sessions.  The session list MUST include\n         all currently active NETCONF sessions.\";\n      list session {\n        key \"session-id\";\n        description\n          \"All NETCONF sessions managed by the NETCONF server\n           MUST be reported in this list.\";\n        leaf session-id {\n          type uint32 {\n            range \"1..max\";\n          }\n          description\n            \"Unique identifier for the session.  This value is the\n             NETCONF session identifier, as defined in RFC 4741.\";\n          reference \"RFC 4741: NETCONF Configuration Protocol\";\n        }\n        leaf transport {\n          type identityref {\n            base transport;\n          }\n          mandatory true;\n          description\n            \"Identifies the transport for each session, e.g.,\n             'netconf-ssh', 'netconf-soap', etc.\";\n        }\n        leaf username {\n          type string;\n          mandatory true;\n          description\n            \"The username is the client identity that was authenticated\n             by the NETCONF transport protocol.  The algorithm used to\n             derive the username is NETCONF transport protocol specific\n             and in addition specific to the authentication mechanism\n             used by the NETCONF transport protocol.\";\n        }\n        leaf source-host {\n          type inet:host;\n          description\n            \"Host identifier of the NETCONF client.  The value\n             returned is implementation specific (e.g., hostname,\n             IPv4 address, IPv6 address)\";\n        }\n        leaf login-time {\n          type yang:date-and-time;\n          mandatory true;\n          description\n            \"Time at the server at which the session was established.\";\n        }\n        uses common-counters {\n          description\n            \"Per-session counters.  Zero based with following reset\n             behaviour:\n               - at start of a session\n               - when max value is reached\";\n        }\n      }\n    }\n    container statistics {\n      description\n        \"Statistical data pertaining to the NETCONF server.\";\n      leaf netconf-start-time {\n        type yang:date-and-time;\n        description\n          \"Date and time at which the management subsystem was\n           started.\";\n      }\n      leaf in-bad-hellos {\n        type yang:zero-based-counter32;\n        description\n          \"Number of sessions silently dropped because an\n           invalid <hello> message was received.  This includes <hello>\n           messages with a 'session-id' attribute, bad namespace, and\n           bad capability declarations.\";\n      }\n      leaf in-sessions {\n        type yang:zero-based-counter32;\n        description\n          \"Number of sessions started.  This counter is incremented\n           when a <hello> message with a <session-id> is sent.\n\n           'in-sessions' - 'in-bad-hellos' =\n              'number of correctly started netconf sessions'\";\n      }\n      leaf dropped-sessions {\n        type yang:zero-based-counter32;\n        description\n          \"Number of sessions that were abnormally terminated, e.g.,\n           due to idle timeout or transport close.  This counter is not\n           incremented when a session is properly closed by a\n           <close-session> operation, or killed by a <kill-session>\n           operation.\";\n      }\n      uses common-counters {\n        description\n          \"Global counters, accumulated from all sessions.\n           Zero based with following reset behaviour:\n             - re-initialization of NETCONF server\n             - when max value is reached\";\n      }\n    }\n  }\n  rpc get-schema {\n    description\n      \"This operation is used to retrieve a schema from the\n       NETCONF server.\n\n       Positive Response:\n         The NETCONF server returns the requested schema.\n\n       Negative Response:\n         If requested schema does not exist, the <error-tag> is\n         'invalid-value'.\n\n         If more than one schema matches the requested parameters, the\n         <error-tag> is 'operation-failed', and <error-app-tag> is\n         'data-not-unique'.\";\n    input {\n      leaf identifier {\n        type string;\n        mandatory true;\n        description\n          \"Identifier for the schema list entry.\";\n      }\n      leaf version {\n        type string;\n        description\n          \"Version of the schema requested.  If this parameter is not\n           present, and more than one version of the schema exists on\n           the server, a 'data-not-unique' error is returned, as\n           described above.\";\n      }\n      leaf format {\n        type identityref {\n          base schema-format;\n        }\n        description\n          \"The data modeling language of the schema.  If this\n           parameter is not present, and more than one formats of\n           the schema exists on the server, a 'data-not-unique' error\n           is returned, as described above.\";\n      }\n    }\n    output {\n      anyxml data {\n        description\n          \"Contains the schema content.\";\n      }\n    }\n  }\n}\n" },
  { file: "ietf-netconf-nmda@2019-01-07.yang", text: "   module ietf-netconf-nmda {\n     yang-version 1.1;\n     namespace \"urn:ietf:params:xml:ns:yang:ietf-netconf-nmda\";\n     prefix ncds;\n\n     import ietf-yang-types {\n       prefix yang;\n       reference\n         \"RFC 6991: Common YANG Data Types\";\n     }\n     import ietf-inet-types {\n       prefix inet;\n       reference\n         \"RFC 6991: Common YANG Data Types\";\n     }\n     import ietf-datastores {\n       prefix ds;\n       reference\n         \"RFC 8342: Network Management Datastore Architecture\n                    (NMDA)\";\n     }\n     import ietf-origin {\n       prefix or;\n       reference\n         \"RFC 8342: Network Management Datastore Architecture\n                    (NMDA)\";\n     }\n     import ietf-netconf {\n       prefix nc;\n       reference\n         \"RFC 6241: Network Configuration Protocol (NETCONF)\";\n     }\n     import ietf-netconf-with-defaults {\n       prefix ncwd;\n       reference\n         \"RFC 6243: With-defaults Capability for NETCONF\";\n     }\n\n     organization\n       \"IETF NETCONF Working Group\";\n\n     contact\n       \"WG Web:   <https://datatracker.ietf.org/wg/netconf/>\n\n        WG List:  <mailto:netconf@ietf.org>\n\n        Author:   Martin Bjorklund\n                  <mailto:mbj@tail-f.com>\n\n        Author:   Juergen Schoenwaelder\n                  <mailto:j.schoenwaelder@jacobs-university.de>\n\n        Author:   Phil Shafer\n                  <mailto:phil@juniper.net>\n\n        Author:   Kent Watsen\n                  <mailto:kent+ietf@watsen.net>\n\n        Author:   Robert Wilton\n                  <mailto:rwilton@cisco.com>\";\n     description\n       \"This YANG module defines a set of NETCONF operations to support\n        the Network Management Datastore Architecture (NMDA).\n\n        The key words 'MUST', 'MUST NOT', 'REQUIRED', 'SHALL', 'SHALL\n        NOT', 'SHOULD', 'SHOULD NOT', 'RECOMMENDED', 'NOT RECOMMENDED',\n        'MAY', and 'OPTIONAL' in this document are to be interpreted as\n        described in BCP 14 (RFC 2119) (RFC 8174) when, and only when,\n        they appear in all capitals, as shown here.\n\n        Copyright (c) 2019 IETF Trust and the persons identified as\n        authors of the code.  All rights reserved.\n\n        Redistribution and use in source and binary forms, with or\n        without modification, is permitted pursuant to, and subject to\n        the license terms contained in, the Simplified BSD License set\n        forth in Section 4.c of the IETF Trust's Legal Provisions\n        Relating to IETF Documents\n        (https://trustee.ietf.org/license-info).\n\n        This version of this YANG module is part of RFC 8526; see\n        the RFC itself for full legal notices.\";\n\n     revision 2019-01-07 {\n       description\n         \"Initial revision.\";\n       reference\n         \"RFC 8526: NETCONF Extensions to Support the Network Management\n                    Datastore Architecture\";\n     }\n\n     feature origin {\n       description\n         \"Indicates that the server supports the 'origin' annotation.\";\n       reference\n         \"RFC 8342: Network Management Datastore Architecture (NMDA)\";\n     }\n\n     feature with-defaults {\n       description\n         \"NETCONF :with-defaults capability.  If the server advertises\n          the :with-defaults capability for a session, then this\n          feature must also be enabled for that session.  Otherwise,\n          this feature must not be enabled.\";\n       reference\n         \"RFC 6243: With-defaults Capability for NETCONF, Section 4; and\n          RFC 8526: NETCONF Extensions to Support the Network Management\n                    Datastore Architecture, Section 3.1.1.2\";\n     }\n\n     rpc get-data {\n       description\n         \"Retrieve data from an NMDA datastore.  The content returned\n          by get-data must satisfy all filters, i.e., the filter\n          criteria are logically ANDed.\n\n          Any ancestor nodes (including list keys) of nodes selected by\n          the filters are included in the response.\n\n          The 'with-origin' parameter is only valid for an operational\n          datastore.  If 'with-origin' is used with an invalid\n          datastore, then the server MUST return an <rpc-error> element\n          with an <error-tag> value of 'invalid-value'.\n\n          The 'with-defaults' parameter only applies to the operational\n          datastore if the NETCONF :with-defaults and\n          :with-operational-defaults capabilities are both advertised.\n          If the 'with-defaults' parameter is present in a request for\n          which it is not supported, then the server MUST return an\n          <rpc-error> element with an <error-tag> value of\n          'invalid-value'.\";\n       input {\n         leaf datastore {\n           type ds:datastore-ref;\n           mandatory true;\n           description\n             \"Datastore from which to retrieve data.\n\n              If the datastore is not supported by the server, then the\n              server MUST return an <rpc-error> element with an\n              <error-tag> value of 'invalid-value'.\";\n         }\n         choice filter-spec {\n           description\n             \"The content filter specification for this request.\";\n           anydata subtree-filter {\n             description\n               \"This parameter identifies the portions of the\n                target datastore to retrieve.\";\n             reference\n               \"RFC 6241: Network Configuration Protocol (NETCONF),\n                          Section 6\";\n           }\n           leaf xpath-filter {\n             if-feature \"nc:xpath\";\n             type yang:xpath1.0;\n             description\n               \"This parameter contains an XPath expression identifying\n                the portions of the target datastore to retrieve.\n\n                If the expression returns a node-set, all nodes in the\n                node-set are selected by the filter.  Otherwise, if the\n                expression does not return a node-set, then the\n                <get-data> operation fails.\n\n                The expression is evaluated in the following XPath\n                context:\n\n                  o  The set of namespace declarations are those in\n                     scope on the 'xpath-filter' leaf element.\n\n                  o  The set of variable bindings is empty.\n\n                  o  The function library is the core function library,\n                     and the XPath functions are defined in Section 10\n                     of RFC 7950.\n\n                  o  The context node is the root node of the target\n                     datastore.\";\n           }\n         }\n         leaf config-filter {\n           type boolean;\n           description\n             \"Filter for nodes with the given value for their 'config'\n              property.  When this leaf is set to 'true', only 'config\n              true' nodes are selected, and when set to 'false', only\n              'config false' nodes are selected.  If this leaf is not\n              present, no nodes are filtered.\";\n         }\n         choice origin-filters {\n           when 'derived-from-or-self(datastore, \"ds:operational\")';\n           if-feature \"origin\";\n           description\n             \"Filters configuration nodes based on the 'origin'\n              annotation.  Configuration nodes that do not have an\n              'origin' annotation are treated as if they have the\n              'origin' annotation 'or:unknown'.\n\n              System state nodes are not affected by origin-filters and\n              thus not filtered.  Note that system state nodes can be\n              filtered with the 'config-filter' leaf.\";\n\n           leaf-list origin-filter {\n             type or:origin-ref;\n             description\n               \"Filter based on the 'origin' annotation.  A\n                configuration node matches the filter if its 'origin'\n                annotation is derived from or equal to any of the given\n                filter values.\";\n           }\n           leaf-list negated-origin-filter {\n             type or:origin-ref;\n             description\n               \"Filter based on the 'origin' annotation.  A\n                configuration node matches the filter if its 'origin'\n                annotation is neither derived from nor equal to any of\n                the given filter values.\";\n           }\n         }\n         leaf max-depth {\n           type union {\n             type uint16 {\n               range \"1..65535\";\n             }\n             type enumeration {\n               enum unbounded {\n                 description\n                   \"All descendant nodes are included.\";\n               }\n             }\n           }\n           default \"unbounded\";\n           description\n             \"For each node selected by the filters, this parameter\n              selects how many conceptual subtree levels should be\n              returned in the reply.  If the depth is 1, the reply\n              includes just the selected nodes but no children.  If the\n              depth is 'unbounded', all descendant nodes are included.\";\n         }\n         leaf with-origin {\n           when 'derived-from-or-self(../datastore, \"ds:operational\")';\n           if-feature \"origin\";\n           type empty;\n           description\n             \"If this parameter is present, the server will return\n              the 'origin' annotation for the nodes that have one.\";\n         }\n         uses ncwd:with-defaults-parameters {\n           if-feature \"with-defaults\";\n         }\n       }\n       output {\n         anydata data {\n           description\n             \"Copy of the source datastore subset that matched\n              the filter criteria (if any).  An empty data\n              container indicates that the request did not\n              produce any results.\";\n         }\n       }\n     }\n\n     rpc edit-data {\n       description\n         \"Edit data in an NMDA datastore.\n\n          If an error condition occurs such that an error severity\n          <rpc-error> element is generated, the server will stop\n          processing the <edit-data> operation and restore the\n          specified configuration to its complete state at\n          the start of this <edit-data> operation.\";\n       input {\n         leaf datastore {\n           type ds:datastore-ref;\n           mandatory true;\n           description\n             \"Datastore that is the target of the <edit-data> operation.\n\n              If the target datastore is not writable, or is not\n              supported by the server, then the server MUST return an\n              <rpc-error> element with an <error-tag> value of\n              'invalid-value'.\";\n         }\n         leaf default-operation {\n           type enumeration {\n             enum merge {\n               description\n                 \"The default operation is merge.\";\n             }\n             enum replace {\n               description\n                 \"The default operation is replace.\";\n             }\n             enum none {\n               description\n                 \"There is no default operation.\";\n             }\n           }\n           default \"merge\";\n           description\n             \"The default operation to use.\";\n         }\n         choice edit-content {\n           mandatory true;\n           description\n             \"The content for the edit operation.\";\n           anydata config {\n             description\n               \"Inline config content.\";\n           }\n           leaf url {\n             if-feature \"nc:url\";\n             type inet:uri;\n             description\n               \"URL-based config content.\";\n           }\n         }\n       }\n     }\n\n     /*\n      * Augment the <lock> and <unlock> operations with a\n      * \"datastore\" parameter.\n      */\n\n     augment \"/nc:lock/nc:input/nc:target/nc:config-target\" {\n       description\n         \"Add NMDA datastore as target.\";\n       leaf datastore {\n         type ds:datastore-ref;\n         description\n           \"Datastore to lock.\n\n            The <lock> operation is only supported on writable\n            datastores.\n\n            If the <lock> operation is not supported by the server on\n            the specified target datastore, then the server MUST return\n            an <rpc-error> element with an <error-tag> value of\n            'invalid-value'.\";\n       }\n     }\n\n     augment \"/nc:unlock/nc:input/nc:target/nc:config-target\" {\n       description\n         \"Add NMDA datastore as target.\";\n       leaf datastore {\n         type ds:datastore-ref;\n         description\n           \"Datastore to unlock.\n\n            The <unlock> operation is only supported on writable\n            datastores.\n\n            If the <unlock> operation is not supported by the server on\n            the specified target datastore, then the server MUST return\n            an <rpc-error> element with an <error-tag> value of\n            'invalid-value'.\";\n       }\n     }\n\n     /*\n      * Augment the <validate> operation with a\n      * \"datastore\" parameter.\n      */\n\n     augment \"/nc:validate/nc:input/nc:source/nc:config-source\" {\n       description\n         \"Add NMDA datastore as source.\";\n       leaf datastore {\n         type ds:datastore-ref;\n         description\n           \"Datastore to validate.\n\n            The <validate> operation is supported only on configuration\n            datastores.\n\n            If the <validate> operation is not supported by the server\n            on the specified target datastore, then the server MUST\n            return an <rpc-error> element with an <error-tag> value of\n            'invalid-value'.\";\n       }\n     }\n   }\n" },
  { file: "ietf-netconf-notifications@2012-02-06.yang", text: "module ietf-netconf-notifications {\n   namespace\n     \"urn:ietf:params:xml:ns:yang:ietf-netconf-notifications\";\n   prefix ncn;\n   import ietf-inet-types { prefix inet; }\n   import ietf-netconf { prefix nc; }\n   organization\n     \"IETF NETCONF (Network Configuration Protocol) Working Group\";\n   contact\n     \"WG Web:   <http://tools.ietf.org/wg/netconf/>\n      WG List:  <mailto:netconf@ietf.org>\n      WG Chair: Bert Wijnen\n                <mailto:bertietf@bwijnen.net>\n      WG Chair: Mehmet Ersue\n                <mailto:mehmet.ersue@nsn.com>\n      Editor:   Andy Bierman\n                <mailto:andy@netconfcentral.org>\";\n   description\n     \"This module defines a YANG data model for use with the\n      NETCONF protocol that allows the NETCONF client to\n      receive common NETCONF base event notifications.\n      Copyright (c) 2012 IETF Trust and the persons identified as\n      the document authors.  All rights reserved.\n      Redistribution and use in source and binary forms, with or\n      without modification, is permitted pursuant to, and subject\n      to the license terms contained in, the Simplified BSD License\n      set forth in Section 4.c of the IETF Trust's Legal Provisions\n      Relating to IETF Documents\n      (http://trustee.ietf.org/license-info).\n      This version of this YANG module is part of RFC 6470; see\n      the RFC itself for full legal notices.\";\n   revision \"2012-02-06\" {\n     description\n       \"Initial version.\";\n     reference\n       \"RFC 6470: NETCONF Base Notifications\";\n   }\n  grouping common-session-parms {\n    description\n      \"Common session parameters to identify a\n       management session.\";\n    leaf username {\n      type string;\n      mandatory true;\n      description\n        \"Name of the user for the session.\";\n    }\n    leaf session-id {\n      type nc:session-id-or-zero-type;\n      mandatory true;\n      description\n        \"Identifier of the session.\n         A NETCONF session MUST be identified by a non-zero value.\n         A non-NETCONF session MAY be identified by the value zero.\";\n    }\n    leaf source-host {\n      type inet:ip-address;\n      description\n        \"Address of the remote host for the session.\";\n    }\n  }\n   grouping changed-by-parms {\n    description\n      \"Common parameters to identify the source\n       of a change event, such as a configuration\n       or capability change.\";\n    container changed-by {\n      description\n        \"Indicates the source of the change.\n         If caused by internal action, then the\n         empty leaf 'server' will be present.\n         If caused by a management session, then\n         the name, remote host address, and session ID\n         of the session that made the change will be reported.\";\n      choice server-or-user {\n        mandatory true;\n        leaf server {\n          type empty;\n          description\n            \"If present, the change was caused\n             by the server.\";\n        }\n        case by-user {\n          uses common-session-parms;\n        }\n      } // choice server-or-user\n    } // container changed-by-parms\n  }\n  notification netconf-config-change {\n    description\n      \"Generated when the NETCONF server detects that the\n       <running> or <startup> configuration datastore\n       has been changed by a management session.\n       The notification summarizes the edits that\n       have been detected.\n       The server MAY choose to also generate this\n       notification while loading a datastore during the\n       boot process for the device.\";\n    uses changed-by-parms;\n    leaf datastore {\n      type enumeration {\n        enum running {\n          description \"The <running> datastore has changed.\";\n        }\n        enum startup {\n          description \"The <startup> datastore has changed\";\n        }\n      }\n      default \"running\";\n      description\n        \"Indicates which configuration datastore has changed.\";\n    }\n    list edit {\n      description\n        \"An edit record SHOULD be present for each distinct\n         edit operation that the server has detected on\n         the target datastore.  This list MAY be omitted\n         if the detailed edit operations are not known.\n         The server MAY report entries in this list for\n         changes not made by a NETCONF session (e.g., CLI).\";\n      leaf target {\n        type instance-identifier;\n        description\n          \"Topmost node associated with the configuration change.\n           A server SHOULD set this object to the node within\n           the datastore that is being altered.  A server MAY\n           set this object to one of the ancestors of the actual\n           node that was changed, or omit this object, if the\n           exact node is not known.\";\n      }\n      leaf operation {\n        type nc:edit-operation-type;\n        description\n          \"Type of edit operation performed.\n           A server MUST set this object to the NETCONF edit\n           operation performed on the target datastore.\";\n      }\n    } // list edit\n  } // notification netconf-config-change\n  notification netconf-capability-change {\n    description\n      \"Generated when the NETCONF server detects that\n       the server capabilities have changed.\n       Indicates which capabilities have been added, deleted,\n       and/or modified.  The manner in which a server\n       capability is changed is outside the scope of this\n       document.\";\n    uses changed-by-parms;\n    leaf-list added-capability {\n      type inet:uri;\n      description\n        \"List of capabilities that have just been added.\";\n    }\n    leaf-list deleted-capability {\n      type inet:uri;\n      description\n        \"List of capabilities that have just been deleted.\";\n    }\n    leaf-list modified-capability {\n      type inet:uri;\n      description\n        \"List of capabilities that have just been modified.\n         A capability is considered to be modified if the\n         base URI for the capability has not changed, but\n         one or more of the parameters encoded at the end of\n         the capability URI have changed.\n         The new modified value of the complete URI is returned.\";\n    }\n  } // notification netconf-capability-change\n  notification netconf-session-start {\n    description\n      \"Generated when a NETCONF server detects that a\n       NETCONF session has started.  A server MAY generate\n       this event for non-NETCONF management sessions.\n       Indicates the identity of the user that started\n       the session.\";\n    uses common-session-parms;\n  } // notification netconf-session-start\n  notification netconf-session-end {\n    description\n      \"Generated when a NETCONF server detects that a\n       NETCONF session has terminated.\n       A server MAY optionally generate this event for\n       non-NETCONF management sessions.  Indicates the\n       identity of the user that owned the session,\n       and why the session was terminated.\";\n    uses common-session-parms;\n    leaf killed-by {\n      when \"../termination-reason = 'killed'\";\n      type nc:session-id-type;\n      description\n        \"The ID of the session that directly caused this session\n         to be abnormally terminated.  If this session was abnormally\n         terminated by a non-NETCONF session unknown to the server,\n         then this leaf will not be present.\";\n    }\n    leaf termination-reason {\n      type enumeration {\n        enum \"closed\" {\n          description\n            \"The session was terminated by the client in normal\n             fashion, e.g., by the NETCONF <close-session>\n             protocol operation.\";\n        }\n        enum \"killed\" {\n          description\n            \"The session was terminated in abnormal\n             fashion, e.g., by the NETCONF <kill-session>\n             protocol operation.\";\n        }\n        enum \"dropped\" {\n          description\n            \"The session was terminated because the transport layer\n             connection was unexpectedly closed.\";\n        }\n        enum \"timeout\" {\n          description\n            \"The session was terminated because of inactivity,\n             e.g., waiting for the <hello> message or <rpc>\n             messages.\";\n        }\n        enum \"bad-hello\" {\n          description\n            \"The client's <hello> message was invalid.\";\n        }\n        enum \"other\" {\n          description\n            \"The session was terminated for some other reason.\";\n        }\n      }\n      mandatory true;\n      description\n        \"Reason the session was terminated.\";\n    }\n  } // notification netconf-session-end\n  notification netconf-confirmed-commit {\n    description\n      \"Generated when a NETCONF server detects that a\n       confirmed-commit event has occurred.  Indicates the event\n       and the current state of the confirmed-commit procedure\n       in progress.\";\n    reference\n      \"RFC 6241, Section 8.4\";\n    uses common-session-parms {\n      when \"confirm-event != 'timeout'\";\n    }\n    leaf confirm-event {\n      type enumeration {\n        enum \"start\" {\n          description\n            \"The confirmed-commit procedure has started.\";\n        }\n        enum \"cancel\" {\n          description\n            \"The confirmed-commit procedure has been canceled,\n             e.g., due to the session being terminated, or an\n             explicit <cancel-commit> operation.\";\n        }\n        enum \"timeout\" {\n          description\n            \"The confirmed-commit procedure has been canceled\n             due to the confirm-timeout interval expiring.\n             The common session parameters will not be present\n             in this sub-mode.\";\n        }\n        enum \"extend\" {\n          description\n            \"The confirmed-commit timeout has been extended,\n             e.g., by a new <confirmed-commit> operation.\";\n        }\n        enum \"complete\" {\n          description\n            \"The confirmed-commit procedure has been completed.\";\n        }\n      }\n      mandatory true;\n      description\n        \"Indicates the event that caused the notification.\";\n    }\n    leaf timeout {\n      when\n        \"../confirm-event = 'start' or ../confirm-event = 'extend'\";\n      type uint32;\n      units \"seconds\";\n      description\n        \"The configured timeout value if the event type\n         is 'start' or 'extend'.  This value represents\n         the approximate number of seconds from the event\n         time when the 'timeout' event might occur.\";\n    }\n  } // notification netconf-confirmed-commit\n}\n" },
  { file: "nc-notifications@2008-07-14.yang", text: "module nc-notifications {\n\n    namespace \"urn:ietf:params:xml:ns:netmod:notification\";\n    prefix \"manageEvent\";\n\n    import ietf-yang-types { prefix yang; }\n    import notifications { prefix ncEvent; }\n\n    organization\n      \"IETF NETCONF WG\";\n\n    contact\n      \"netconf@ietf.org\";\n\n    description\n      \"Conversion of the 'manageEvent' XSD in the NETCONF\n       Notifications RFC.\";\n\n    reference\n      \"RFC 5277\";\n\n    revision 2008-07-14 {\n      description \"RFC 5277 version.\";\n    }\n\n    container netconf {\n      description \"Top-level element in the notification namespace\";\n\n      config false;\n\n      container streams {\n        description\n          \"The list of event streams supported by the system. When\n           a query is issued, the returned set of streams is\n           determined based on user privileges.\";\n\n        list stream {\n          description\n            \"Stream name, description and other information.\";\n          key name;\n          min-elements 1;\n\n          leaf name {\n            description\n              \"The name of the event stream. If this is the default\n               NETCONF stream, this must have the value 'NETCONF'.\";\n            type ncEvent:streamNameType;\n          }\n\n          leaf description {\n            description\n              \"A description of the event stream, including such\n               information as the type of events that are sent over\n               this stream.\";\n            type string;\n            mandatory true;\n          }\n\n          leaf replaySupport {\n            description\n              \"A description of the event stream, including such\n               information as the type of events that are sent over\n               this stream.\";\n            type boolean;\n            mandatory true;\n          }\n\n          leaf replayLogCreationTime {\n            description\n              \"The timestamp of the creation of the log used to support\n               the replay function on this stream. Note that this might\n               be earlier then the earliest available notification in\n               the log. This object is updated if the log resets for\n               some reason.  This object MUST be present if replay is\n               supported.\";\n            type yang:date-and-time;   // xsd:dateTime is wrong!\n          }\n\n          leaf replayLogAgedTime {\n            description\n              \"The timestamp of the last notification\n               aged out of the log. This\n               object MUST be present if replay is\n               supported and any notifications\n               have been aged out of the log.\";\n            type yang:date-and-time;\n          }\n        }\n      }\n    }\n\n    notification replayComplete {\n      description\n        \"This notification is sent to signal the end of a replay\n         portion of a subscription.\";\n    }\n\n    notification notificationComplete {\n      description\n        \"This notification is sent to signal the end of a notification\n         subscription. It is sent in the case that stopTime was\n         specified during the creation of the subscription..\";\n    }\n\n}\n" },
  { file: "net-netconf-server-control@2026-11-15.yang", text: "module net-netconf-server-control {\n  yang-version 1.1;\n  namespace \"urn:node-net:yang:net-netconf-server-control\";\n  prefix nnsc;\n\n  import ietf-yang-types {\n    prefix yang;\n  }\n  import ietf-netconf-acm {\n    prefix nacm;\n  }\n\n  organization\n    \"node-net\";\n  description\n    \"The control module of net-netconf-server: for tests and tutorials\n     to reset the server, inject faults, switch quirks, send\n     notifications, set state, and snapshot and restore datastores.\n\n     The server implements it only when the deployment enables the\n     control module, and it is never meant for a server fronting a\n     real system. Sessions of the deployment's control users are\n     exempt from quirks and faults, so a server whose quirks break\n     the protocol can still be controlled.\n\n     Settings and content that have their own shape are given as RFC\n     7951 JSON text.\n\n     Where the server enforces NACM (RFC 8341), every operation here\n     is denied unless a rule permits it, so a control user also needs\n     a permitting rule or a recovery session.\";\n\n  revision 2026-11-15 {\n    description\n      \"Every rpc is nacm:default-deny-all.\";\n  }\n  revision 2026-11-13 {\n    description\n      \"Initial revision.\";\n  }\n\n  typedef json {\n    type string;\n    description\n      \"RFC 7951 JSON text.\";\n  }\n\n  container control {\n    config false;\n    description\n      \"What the control module has changed.\";\n    container faults {\n      description\n        \"Faults waiting to fire.\";\n      list fault {\n        key \"id\";\n        leaf id {\n          type uint32;\n          description\n            \"The fault's id, as inject-fault returned it.\";\n        }\n        leaf target {\n          type string;\n          description\n            \"Which session it is for: session N, user NAME, or\n             next-session.\";\n        }\n        leaf trigger {\n          type string;\n          description\n            \"When it fires: next-rpc, an operation name, or\n             immediate.\";\n        }\n        leaf action {\n          type string;\n          description\n            \"What it does.\";\n        }\n        leaf remaining {\n          type uint32;\n          description\n            \"How many more times it fires.\";\n        }\n        leaf session-id {\n          type uint32;\n          description\n            \"For a next-session fault, the session it went to.\";\n        }\n      }\n    }\n    container quirks {\n      description\n        \"Quirks changed at run time; the device definition's quirks\n         are not listed.\";\n      list quirk {\n        key \"name scope\";\n        leaf name {\n          type string;\n          description\n            \"The quirk's name.\";\n        }\n        leaf scope {\n          type string;\n          description\n            \"new-sessions, or session N.\";\n        }\n        leaf settings {\n          type json;\n          description\n            \"The quirk's settings, or absent when it was turned off.\";\n        }\n      }\n    }\n    container snapshots {\n      description\n        \"Saved snapshots.\";\n      list snapshot {\n        key \"name\";\n        leaf name {\n          type string;\n          description\n            \"The snapshot's name.\";\n        }\n        leaf taken {\n          type yang:date-and-time;\n          description\n            \"When it was taken.\";\n        }\n      }\n    }\n  }\n\n  rpc reset {\n    nacm:default-deny-all;\n    description\n      \"Put every datastore back to the device definition's initial\n       data, and clear locks, a pending confirmed commit, faults,\n       run-time quirk changes and snapshots. Providers are not\n       called. Completes before its ok is sent.\";\n    input {\n      leaf end-other-sessions {\n        type boolean;\n        default \"false\";\n        description\n          \"Also end every other session, as kill-session would.\";\n      }\n    }\n  }\n\n  rpc inject-fault {\n    nacm:default-deny-all;\n    description\n      \"Make a session misbehave.\";\n    input {\n      choice target {\n        mandatory true;\n        leaf session-id {\n          type uint32;\n          description\n            \"The session with this id.\";\n        }\n        leaf username {\n          type string;\n          description\n            \"Every session of this user.\";\n        }\n        leaf next-session {\n          type empty;\n          description\n            \"The next session to open.\";\n        }\n      }\n      choice trigger {\n        leaf next-rpc {\n          type empty;\n          description\n            \"The next request (the default).\";\n        }\n        leaf on-operation {\n          type string;\n          description\n            \"The next request for this operation, by its local name.\";\n        }\n        leaf immediately {\n          type empty;\n          description\n            \"At once.\";\n        }\n      }\n      leaf count {\n        type uint32 {\n          range \"1..max\";\n        }\n        default \"1\";\n        description\n          \"How many times it fires.\";\n      }\n      choice action {\n        mandatory true;\n        container rpc-error {\n          description\n            \"Reply with an rpc-error instead.\";\n          leaf error-type {\n            type enumeration {\n              enum transport;\n              enum rpc;\n              enum protocol;\n              enum application;\n            }\n            default \"application\";\n          }\n          leaf error-tag {\n            type string;\n            default \"operation-failed\";\n          }\n          leaf error-message {\n            type string;\n          }\n        }\n        leaf no-reply {\n          type empty;\n          description\n            \"Send no reply.\";\n        }\n        leaf delay {\n          type uint32;\n          units \"milliseconds\";\n          description\n            \"Send the reply after this long.\";\n        }\n        leaf drop {\n          type empty;\n          description\n            \"Drop the connection.\";\n        }\n        leaf no-hello {\n          type empty;\n          description\n            \"Send no hello (for next-session).\";\n        }\n        leaf-list unsolicited {\n          type string;\n          description\n            \"Send these messages before the reply.\";\n        }\n        leaf raw-bytes {\n          type string;\n          description\n            \"Write this text in place of the framed reply.\";\n        }\n      }\n    }\n    output {\n      leaf id {\n        type uint32;\n        description\n          \"The fault's id, for clear-faults.\";\n      }\n    }\n  }\n\n  rpc clear-faults {\n    nacm:default-deny-all;\n    description\n      \"Remove one fault, or all of them.\";\n    input {\n      leaf id {\n        type uint32;\n        description\n          \"The fault to remove; all of them when absent.\";\n      }\n    }\n    output {\n      leaf cleared {\n        type uint32;\n        description\n          \"How many were removed.\";\n      }\n    }\n  }\n\n  rpc set-quirk {\n    nacm:default-deny-all;\n    description\n      \"Turn a quirk on with its settings, or off, for new sessions or\n       for one session. Quirks that act at session start (such as\n       broken chunked framing) reach only sessions opened afterwards.\";\n    input {\n      leaf name {\n        type string;\n        mandatory true;\n      }\n      choice value {\n        leaf settings {\n          type json;\n          description\n            \"true for the defaults, or an object of settings.\";\n        }\n        leaf off {\n          type empty;\n          description\n            \"Turn the quirk off.\";\n        }\n      }\n      leaf session-id {\n        type uint32;\n        description\n          \"The session to change; new sessions when absent.\";\n      }\n    }\n  }\n\n  rpc send-notification {\n    nacm:default-deny-all;\n    description\n      \"Send a notification of the device's schema to every matching\n       subscription. Its content is validated as for providers'\n       notifications.\";\n    input {\n      leaf path {\n        type string;\n        mandatory true;\n        description\n          \"The notification: /module:name, or for a nested one the\n           data path of its parent followed by its name.\";\n      }\n      leaf content {\n        type json;\n        default \"{}\";\n        description\n          \"The notification's content.\";\n      }\n      leaf event-time {\n        type yang:date-and-time;\n        description\n          \"The eventTime to send; the server's clock when absent.\";\n      }\n    }\n  }\n\n  rpc set-state {\n    nacm:default-deny-all;\n    description\n      \"Apply an edit to the state data the server holds for\n       <operational>. Configuration can't be changed this way.\";\n    input {\n      leaf edit {\n        type json;\n        mandatory true;\n        description\n          \"The edit, with NETCONF edit annotations where needed.\";\n      }\n    }\n  }\n\n  rpc snapshot {\n    nacm:default-deny-all;\n    description\n      \"Save every datastore under a name, in memory.\";\n    input {\n      leaf name {\n        type string;\n        mandatory true;\n      }\n    }\n  }\n\n  rpc restore {\n    nacm:default-deny-all;\n    description\n      \"Put every datastore back to a snapshot. Providers are not\n       called; netconf-config-change reports the change to running.\";\n    input {\n      leaf name {\n        type string;\n        mandatory true;\n      }\n    }\n  }\n}\n" },
  { file: "net-netconf-server-monitoring@2026-11-15.yang", text: "module net-netconf-server-monitoring {\n  yang-version 1.1;\n  namespace \"urn:node-net:yang:net-netconf-server-monitoring\";\n  prefix nnsm;\n\n  import ietf-netconf-monitoring {\n    prefix ncm;\n  }\n\n  organization\n    \"node-net\";\n  description\n    \"What net-netconf-server reports about itself beyond RFC 6022's\n     NETCONF monitoring: its own transport identity, whether each\n     session is a NACM recovery session, and the providers registered\n     with it.\";\n\n  revision 2026-11-15 {\n    description\n      \"Added the recovery leaf to each session.\";\n  }\n  revision 2026-11-13 {\n    description\n      \"Initial revision.\";\n  }\n\n  identity in-process {\n    base ncm:transport;\n    description\n      \"A session opened in the same process as the server, with no\n       network transport: server.transport() and serve() on an\n       in-memory connection.\";\n  }\n\n  augment \"/ncm:netconf-state/ncm:sessions/ncm:session\" {\n    description\n      \"What the server knows about a session beyond RFC 6022.\";\n    leaf recovery {\n      type boolean;\n      description\n        \"True for a recovery session (RFC 8341 Section 3.3.3), which\n         NACM does not restrict.\";\n    }\n  }\n\n  container providers {\n    config false;\n    description\n      \"The providers registered with the server: code that adds\n       behaviour (read hooks, applying changes to a backend, RPCs and\n       actions) to a subtree of the data.\";\n    list provider {\n      key \"path\";\n      description\n        \"One provider, in registration order.\";\n      leaf path {\n        type string;\n        description\n          \"The schema data path the provider is registered on, as in\n           RFC 7951: /module:top/child.\";\n      }\n      leaf out-of-sync {\n        type boolean;\n        description\n          \"True when the backend is known to differ from the running\n           configuration for this subtree: a commit failed and undoing\n           it failed too, or the provider reported drift it could not\n           reconcile. The provider clears it once reconciled.\";\n      }\n      leaf reason {\n        type string;\n        description\n          \"Why the subtree is out of sync.\";\n      }\n    }\n  }\n}\n" },
  { file: "notifications@2008-07-14.yang", text: "module notifications {\n\n    namespace \"urn:ietf:params:xml:ns:netconf:notification:1.0\";\n    prefix \"ncEvent\";\n\n    import ietf-yang-types { prefix yang; }\n\n    organization\n      \"IETF NETCONF WG\";\n\n    contact\n      \"netconf@ops.ietf.org\";\n\n    description\n      \"Conversion of the 'ncEvent' XSD in the\n       NETCONF Notifications RFC.\";\n\n    reference\n      \"RFC 5277.\";\n\n    revision 2008-07-14 {\n      description \"RFC 5277 version.\";\n    }\n\n    typedef streamNameType {\n      description\n        \"The name of an event stream.\";\n      type string;\n    }\n\n    rpc create-subscription {\n      description\n        \"The command to create a notification subscription. It\n         takes as argument the name of the notification stream\n         and filter. Both of those options limit the content of\n         the subscription. In addition, there are two time-related\n         parameters, startTime and stopTime, which can be used to\n         select the time interval of interest to the notification\n         replay feature.\";\n\n      input {\n        leaf stream {\n          description\n            \"An optional parameter that indicates which stream of events\n             is of interest. If not present, then events in the default\n             NETCONF stream will be sent.\";\n          type streamNameType;\n          default \"NETCONF\";\n        }\n\n        anyxml filter {\n          description\n            \"An optional parameter that indicates which subset of all\n             possible events is of interest. The format of this\n             parameter is the same as that of the filter parameter\n             in the NETCONF protocol operations. If not present,\n             all events not precluded by other parameters will\n             be sent.\";\n        }\n\n        leaf startTime {\n          description\n            \"A parameter used to trigger the replay feature and\n             indicates that the replay should start at the time\n             specified. If start time is not present, this is not a\n             replay subscription.\";\n          type yang:date-and-time;\n        }\n\n        leaf stopTime {\n          // must \". >= ../startTime\";\n          description\n            \"An optional parameter used with the optional replay\n             feature to indicate the newest notifications of\n             interest. If stop time is not present, the notifications\n             will continue until the subscription is terminated.\n             Must be used with startTime.\";\n          type yang:date-and-time;\n        }\n      }\n    }\n\n   /*container notification {\n      description \"internal struct to start a notification\";\n      config false;\n\n      leaf eventTime {\n         mandatory true;\n         type yang:date-and-time;\n      }\n\n      // eventType and any data content goes here\n   }*/\n}\n\n" },
];
